import{_ as o,o as t,c as a,a5 as s}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"3.2.8 Sign Out","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-8-sign-out/spec.md","filePath":"feature/authentication/3-2-8-sign-out/spec.md"}'),r={name:"feature/authentication/3-2-8-sign-out/spec.md"};function i(n,e,d,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-2-8-sign-out" tabindex="-1">3.2.8 Sign Out <a class="header-anchor" href="#_3-2-8-sign-out" aria-label="Permalink to &quot;3.2.8 Sign Out&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.2.8</td></tr><tr><td>Feature</td><td>Sign Out (Logout)</td></tr><tr><td>Domain</td><td>Authentication (FR 3.2)</td></tr><tr><td>Role</td><td>Any signed-in USER</td></tr><tr><td>Version</td><td>4.0 — 2026-09-25 — FE now calls the logout endpoint — token blacklisting is real, not just local state clear</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a signed-in user clicks &quot;Log out&quot; in the account/navbar menu (or the dashboard&#39;s logout button).</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Any authenticated USER.</li><li><strong>Purpose:</strong> End the current session. Blacklists the current access and refresh token <code>jti</code> values server-side and records a LOGOUT audit event, then clears local client state and redirects to <code>/login</code>.</li><li><strong>Interface:</strong> A &quot;Log out&quot; menu item / icon button in the Navbar and in the Dashboard page header (not a full-page confirmation screen).</li><li><strong>Data Processing:</strong> <code>Navbar.handleLogout</code> fires <code>authService.logout()</code> (<code>POST /api/v1/auth/logout</code>, fire-and-forget, best-effort — the call is not awaited before proceeding) and, independent of that call&#39;s outcome, immediately clears <code>user</code>, <code>accessToken</code>, <code>refreshToken</code>, <code>isAuthenticated</code>, <code>systemRole</code> via <code>clearAuth()</code> and navigates to <code>/login</code>. On the backend, <code>AuthController.logout</code> reads the <code>Authorization: Bearer &lt;accessToken&gt;</code> header, the <code>refreshToken</code> cookie, <code>X-Forwarded-For</code> (ipAddress) and <code>User-Agent</code> headers, blacklists the access token&#39;s <code>jti</code> (best-effort) and the refresh token&#39;s <code>jti</code> (best-effort), writes an audit log when the access token yielded a user id, clears the <code>refreshToken</code> cookie, and returns 200 with no data.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Sign Out entry points (no dedicated Sign Out screen exists):</p><ul><li>Navbar: a &quot;Log out&quot; icon button (<code>LogOut</code> icon, <code>Navbar.tsx</code>) inside the account area, calling <code>handleLogout()</code>.</li><li>Dashboard page header: a &quot;Log out&quot; button (<code>dashboard.page.logout</code> — <code>pages/dashboard/index.tsx</code>, via <code>useDashboardData().handleLogout</code>), calling <code>clearAuth()</code> directly (does not go through <code>Navbar.handleLogout</code>, so it does not call the logout endpoint — see Business Rules).</li><li>After either action, <code>isAuthenticated</code> becomes <code>false</code>; <code>AuthGuard</code> (<code>components/layout/AuthGuard.tsx</code>) then redirects any protected route to <code>/login</code>.</li><li><code>lib/axios.ts</code> also calls <code>useAuthStore.getState().logout()</code> automatically on a 401 response interceptor (session-expired forced logout), toast MSG22 in that case — this path also does not call the logout endpoint (the session is already invalid).</li><li>The landing-page navbar (<code>components/landing/Navbar.tsx</code>) has no logout handler — it is shown only to unauthenticated visitors.</li></ul><p>⚠ <strong>BA conflict (needs team decision):</strong> the Dashboard page header&#39;s own &quot;Log out&quot; button (<code>useDashboardData().handleLogout</code>) still calls <code>clearAuth()</code> directly and does <strong>not</strong> go through <code>authService.logout()</code>, unlike <code>Navbar.handleLogout</code>. A user signing out from the dashboard header therefore still leaves their access/refresh token unblacklisted server-side, the same gap this revision closes for the Navbar path. Needs a team decision: either route the dashboard header&#39;s logout through the same <code>authService.logout()</code> call, or confirm this entry point is being deprecated in favor of the Navbar&#39;s.</p><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required (backend):</strong> <code>Authorization: Bearer &lt;accessToken&gt;</code> header. <code>refreshToken</code> cookie is optional (its absence does not fail the request).</li><li><strong>Input optional (backend):</strong> <code>X-Forwarded-For</code> (ipAddress), <code>User-Agent</code> (userAgent), <code>X-Request-Id</code> (requestId, generated server-side if absent).</li><li><strong>Input (frontend):</strong> none — <code>authService.logout()</code> sends no body; the browser attaches the <code>Authorization</code> header via the axios instance&#39;s interceptor and the <code>refreshToken</code> cookie automatically.</li><li><strong>System data:</strong> userId resolved from the access token&#39;s JWT subject (only if the token parses); the token&#39;s <code>jti</code> for blacklisting; the caller&#39;s ipAddress/userAgent for the audit record.</li><li><strong>Output:</strong> <code>ApiResponse&lt;Void&gt;</code> — <code>data</code> is <code>null</code> on success. The <code>refreshToken</code> cookie is cleared (<code>MaxAge=0</code>, same <code>Path=/api/v1/auth</code>, <code>HttpOnly</code>, <code>Secure</code>, <code>SameSite=Strict</code> as when login sets it).</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-14:</strong> &quot;Sign-out blacklists both access and refresh token <code>jti</code> values and clears the refresh cookie.&quot; <ul><li>Access token blacklisting and refresh token blacklisting are each wrapped independently in their own try/catch for <code>JwtException</code> — either one failing (expired, malformed, wrong signature) is swallowed silently and does <strong>not</strong> fail the request. <code>AuthServiceImpl.logout</code> never throws.</li><li>The refresh cookie is cleared by the controller unconditionally, on every successful (200) response — regardless of whether blacklisting succeeded.</li><li>The frontend call is itself best-effort: <code>authService.logout().catch(() =&gt; {})</code> in <code>Navbar.handleLogout</code> swallows any error (network failure, already-expired token, 401) and proceeds to clear local state regardless — see Abnormal Cases.</li></ul></li><li><strong>BR-16:</strong> Security events (LOGIN, LOGOUT, PASSWORD_RESET) are always persisted to the audit log with IP + user agent. For logout, the <code>AuditLog</code> (action=<code>LOGOUT</code>, resourceType=<code>USER</code>, resourceId=userId, ipAddress, userAgent) is written <strong>only if</strong> the access token successfully parsed to a userId; if the access token could not be parsed, no audit row is written for that logout call — success is still reported.</li><li>Only the tokens for the current device/session are invalidated; refresh tokens held by other devices/sessions are unaffected (unlike a password change, which invalidates every refresh token — see FR 3.2.x Change Password).</li><li>Missing or malformed <code>Authorization</code> header is the <strong>one</strong> case that is not idempotent/best-effort on the backend: it is rejected before <code>authService.logout(...)</code> (Java service) is ever called (see Abnormal Cases). This never surfaces to the FE user because <code>Navbar.handleLogout</code> clears local state and navigates away regardless of the API outcome.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li><code>Authorization</code> header missing, or present but not starting with <code>&quot;Bearer &quot;</code> → 401 <code>INVALID_CREDENTIALS</code>. Note: unlike every other authenticated endpoint in <code>AuthController</code> (which throw <code>BusinessException(INVALID_CREDENTIALS)</code> via the shared <code>requireUserId</code> helper, handled by the global exception handler), <code>logout</code> checks this inline in the controller method itself and calls <code>response.setStatus(401)</code> + returns <code>ApiResponse.error(...)</code> directly — a different code path from the rest of the controller. This is a code-quality inconsistency worth a cleanup ticket, but it produces the same 401/<code>INVALID_CREDENTIALS</code> result, so it is not a behavioral BA conflict. The FE never shows this as an error — see Abnormal Cases.</li><li>Expired or otherwise unparsable access token (header well-formed) → not an error; sign-out still returns 200.</li><li>Missing, expired, or unparsable refresh token → not an error; sign-out still returns 200.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>User clicks &quot;Log out&quot; in the Navbar.</li><li><code>Navbar.handleLogout</code> calls <code>authService.logout()</code> (<code>POST /api/v1/auth/logout</code> with <code>Authorization: Bearer &lt;accessToken&gt;</code> header and <code>refreshToken</code> cookie sent automatically) without awaiting it, and swallows any rejection with <code>.catch(() =&gt; {})</code>.</li><li>In parallel/independent of step 2&#39;s outcome, <code>Navbar.handleLogout</code> calls <code>clearAuth()</code> (clears <code>user</code>, <code>accessToken</code>, <code>refreshToken</code>, <code>isAuthenticated</code>, <code>systemRole</code> from the auth store and resets the workspace store) and navigates to <code>/login</code>. The client does not wait for the API response before proceeding.</li><li>On the backend, the controller validates the <code>Authorization</code> header format; on success it strips the <code>Bearer </code> prefix and calls <code>authService.logout(accessToken, refreshToken, ipAddress, userAgent)</code>.</li><li>The service parses the access token; on success it extracts the userId and blacklists the access token&#39;s <code>jti</code> (BR-14).</li><li>If a refresh token is present, the service blacklists its <code>jti</code> too (BR-14), independent of step 5&#39;s outcome.</li><li>If a userId was resolved in step 5, the service writes a LOGOUT <code>AuditLog</code> with ipAddress and userAgent (BR-16).</li><li>The controller clears the <code>refreshToken</code> cookie (<code>MaxAge=0</code>) and returns 200 <code>ApiResponse.ok(null)</code>.</li><li>By the time the response arrives (if it arrives before the browser navigates away), the user is typically already on <code>/login</code>; no toast is shown for the success case since the UI has already moved on.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><p>4.a1: <code>Authorization</code> header missing or not starting with <code>&quot;Bearer &quot;</code> → the controller itself sets HTTP 401 and returns <code>ApiResponse.error(INVALID_CREDENTIALS, ...)</code> inline, without calling <code>authService.logout</code>. 4.a2: <code>authService.logout()</code>&#39;s promise rejects; <code>Navbar.handleLogout</code>&#39;s <code>.catch(() =&gt; {})</code> swallows it — the frontend still clears its local state and navigates to <code>/login</code> with no user-facing error, per BR-14&#39;s best-effort FE contract.</p><p>5.a1: Access token is present with a valid <code>Bearer </code> prefix but is expired or fails to parse (<code>JwtException</code>) → caught and ignored; <code>userId</code> stays <code>null</code>; sign-out proceeds as idempotent success (no audit row written). 5.a2: Refresh token blacklisting (step 6) still runs if a refresh token is present.</p><p>6.a1: Refresh token is absent, expired, or fails to parse → caught and ignored; sign-out still returns 200. 6.a2: The access token&#39;s blacklisting result (step 5) is unaffected.</p><p>N.a1 (network failure / API unreachable): the <code>POST /api/v1/auth/logout</code> call throws a network error (offline, timeout, server down) → the promise rejects and <code>.catch(() =&gt; {})</code> swallows it. The frontend proceeds exactly as in the success case: local state cleared, redirect to <code>/login</code>, no error toast. The server-side token is not blacklisted in this case and remains valid until natural expiry.</p><p>N.a2 (forced logout, session already expired): <code>lib/axios.ts</code>&#39;s response interceptor calls <code>useAuthStore.getState().logout()</code> on a 401 from any API call (expired/invalid session), which triggers the same local-only clear-and-redirect, with toast MSG22 (&quot;session expired&quot;) instead of the normal flow. This path does not call <code>authService.logout()</code> — the session is already considered invalid, so no additional server round trip is made.</p><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The access token&#39;s and refresh token&#39;s <code>jti</code> values are blacklisted server-side (best-effort — see BR-14), the <code>refreshToken</code> cookie is cleared, and — when the access token was resolvable and the request reached the backend — a LOGOUT audit log row exists with ipAddress and userAgent.</li><li>Regardless of the API call&#39;s outcome, the frontend&#39;s local auth/workspace state is cleared and the user is redirected to <code>/login</code>.</li><li>Sessions on other devices are unaffected.</li><li>If the API call failed (network error, already-expired token) the server-side token may remain valid until natural expiry, but the user is signed out of the current browser session either way (see Abnormal Cases N.a1).</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Remembering/highlighting the last-used sign-in method (e.g. &quot;used last time&quot; on <code>/login</code>) — no such field or local-storage key exists in the current frontend code (<code>authStore.ts</code>, <code>Navbar.tsx</code>, login page); any earlier spec mentioning it does not match the codebase and has been removed from this revision.</li><li>Server-side &quot;logout all devices&quot; — out of scope for this FR; see Change Password, which does invalidate every refresh token.</li><li>Wiring the Dashboard page header&#39;s separate logout button through <code>authService.logout()</code> — see BA conflict above.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p>Section5_Requirement_Appendix.md (BR-14, BR-16; MSG22) — read-only, not modified by this revision.</p>',32)])])}const f=o(r,[["render",i]]);export{g as __pageData,f as default};
